import {MUTATION_DETAILS} from './mutation-help.js';
import {EVOLUTION_RULES as R,MUTATION_GROUPS,MUTATION_LABELS} from './brain-evolution-rules.js';
import {ATTENTION_INPUTS,DUAL_TYPE_LAYOUT} from './dual-brain-layout.js';
import {ATTENTION_REFERENCE_OPERATIONS} from './brain-cost.js';
import {SUBSTEPS,DT,DECISION_COST,REPEAT_COST,ACTION_DURATIONS} from './action-timing.js';
import {v,p,a,table,details} from './guide-markup.js';
/** Текущие статьи схемы двух сетей. Числа импортируются из владельцев;
 * исходные статьи ссылаются сюда, не содержат вторую версию правил. */
export const DUAL_GUIDE_TEXT={
 'guide-genome-body':
 p(`Геном схемы v${v(DUAL_TYPE_LAYOUT.version)} содержит наследуемые веса, две изменяемые структуры и свойства ощущений, памяти и обучения. В течение жизни основной мозг добавляет к исходным весам личные поправки. При рождении ребёнок получает исходную основу с мутациями; карты памяти и обученные поправки родителя не копируются.`)
 +table('Что наследуется',['Область','Содержание'],[
 ['Основной оценщик','Фиксированный кодировщик клеток, проекции операции/цели и прямая оценка; изменяемый контекст ситуации. Все исходные веса могут мутировать.'],
 ['Диспетчер внимания',`Отдельная ациклическая сеть с ${v(ATTENTION_INPUTS)} входами и одним выходом. Его структура и веса наследуются; личного обучения нет.`],
 ['Поведенческие свойства','Чувствительности к энергии, здоровью и желудку, свойства памяти и обучения.'],
 ['Регуляторы мутаций',`По вероятности и силе для каждой из ${v(MUTATION_GROUPS.length)} групп. Всего ${v(2*MUTATION_GROUPS.length)} регуляторов.`]])
 +'<h4>Пример наследования</h4>'
 +p('За жизнь родитель изменил личную оценку еды. Ребёнок получает его наследуемые веса, а не эту личную поправку. При включённых мутациях некоторые веса и свойства изменяются, а структуры двух сетей могут получить или потерять элементы.')
 +details('Формат и совместимость',p('Размер массива зависит от двух графов. Метаданные задают версию и порядок областей: фиксированные веса, параметры контекста, свойства, параметры диспетчера, отдельные пары регуляторов и целочисленная топология. Прежние геномы не преобразуются в новую схему автоматически. Старые результаты опытов доступны для анализа; отсутствие новых полей означает неизвестное значение, а не ноль. Полное сохранение мира отдельно хранит личное состояние.'))
 +p(`Дальше: ${a('structure-evolution','правила мутаций')}, ${a('learning','личное обучение')}, ${a('saves','сохранение мира')}, ${a('genome-analysis','анализ генома')}.`),

 'guide-structure-evolution-body':
 p('Структура меняется у двух сетей: контекста ситуации и малого диспетчера. Кодировщик клеток, проекции и прямая оценка сохраняют устройство. Сеть может усложняться или упрощаться при рождении; в течение жизни набор нейронов и связей остаётся тем же.')
 +details('Что именно мутирует в каждой группе?',table('Блоки мутаций',['Группа','Назначение','Наследственные изменения'],Object.entries(MUTATION_DETAILS).map(([key,d])=>[MUTATION_LABELS[key],d.role,d.changes])))
 +table('Начало опыта',['Параметр','По умолчанию'],[
 ['Скрытые нейроны','Нет скрытых нейронов. Входы соединены непосредственно с обязательными выходами.'],
 ['Связность',`${v(R.initialConnections,'%')} относительно полного соединения соседних непустых уровней. Ноль означает отсутствие связей; смещения выходов остаются.`],
 ['Пределы',`${v(R.maxNeurons)} скрытых нейрона и ${v(R.maxLayers)} скрытых слоя отдельно для каждой сети; пользователь может изменить их в технических пределах.`],
 ['Стартовая вероятность',`${v(R.initialRateMin*100,'%')}–${v(R.initialRateMax*100,'%')} независимо для ${v(MUTATION_GROUPS.length)} групп.`],
 ['Стартовая сила',`${v(R.initialStrengthMin)}–${v(R.initialStrengthMax)}. Это начальные диапазоны, не верхние пределы наследования.`]])
 +table('Независимые группы мутаций',['Группа','Настройка'],MUTATION_GROUPS.map(key=>[MUTATION_LABELS[key],'Собственные наследуемые вероятность и сила']))
 +p('В стартовых условиях мутации потомков включены для всех групп. Для контекста и диспетчера веса и структура имеют отдельные строки и пары регуляторов. Снятая галочка запрещает выбранный тип мутации и изменение его пары. При выключенных мутациях весов структура всё ещё может удалить связь; численные значения оставшихся связей сохраняются. Общий запрет мутаций останавливает все группы; запрет структурных мутаций ограничивает только изменение схемы. Личное обучение задаётся отдельно и может менять личные поправки даже при выключенных наследуемых мутациях.')
 +'<h4>Пример силы мутации</h4>'
 +p('Учебный пример: при силе 0,1 числовая мутация меняет вес не более чем на ±0,1. Для сети с десятью скрытыми нейронами ожидаемый бюджет изменения узлов — один. Дробная часть бюджета округляется случайно; поэтому даже сеть без скрытых нейронов может получить первый узел.')
 +details('Точные правила рождения',p('Для каждого веса проводится независимая проверка вероятности своей группы. У каждой изменяемой сети есть другая пара регуляторов для структуры и отдельная проверка её вероятности на структурное событие. Весовые и структурные изменения независимы и могут совпасть при рождении. Сила структурной группы задаёт её собственный бюджет; она не меняет численные значения сохранившихся весов. Структура меняется только у контекста и диспетчера.')
 +p('Величина структурного события пропорциональна силе и текущему числу узлов/связей, с минимумом размера базы один. Целая часть бюджета берётся сразу, дробная — с соответствующей вероятностью. Добавление и удаление выбираются симметрично; невозможные правки пропускаются. Число попыток ограничено техническими пределами.')
 +p('Новый скрытый нейрон получает ненулевую входящую связь и нулевую исходящую. Эта обязательная пара относится к добавлению нейрона. Старые пути сохраняются: изолированное добавление не меняет выход сети. Удаление работающего узла может изменить оценки; его связи удаляются вместе с ним. Пустые уровни сжимаются. Связи идут только вперёд, могут пропускать слои; циклов нет.')
 +p('Регуляторы каждой группы тоже мутируют по собственной родительской паре. Правила рождения фиксируются по родителю до любых изменений; новые значения управляют уже следующим поколением. Вероятность имеет положительный нижний предел, сила ограничена представимостью конечного числа. Веса сохраняют свои числовые ограничения. Нулевой вес существующего ребра отличается от отсутствующей связи: основной мозг может обучить его за жизнь; диспетчер получает влияние только через последующую наследственную мутацию.'))
 +p(`См. ${a('brain-structure','состав мозга')}, ${a('brain-cost','вычислительную цену')}, ${a('genome','состав генома')}, ${a('experiment-design','сопоставимые опыты')}.`),

 'guide-choice-body':
 p('Основной мозг оценивает физически допустимые действия и отдельно — покой. Действие допускается к выбору, когда его оценка лучше оценки покоя. Если таких действий нет, житель остаётся в покое. Покой не имеет срока завершения: тело продолжает жить, а диспетчер проверяет, нужен ли новый основной выбор.')
 +'<h4>Пример сравнения</h4>'
 +p('Учебный пример: оценка покоя −3, оценка движения −2. Движение допускается, хотя его оценка отрицательна. При равных оценках и нулевом пороге выбирается покой. Поэтому запрет всех отрицательных Q не соответствует этой политике.')
 +details('Допуск и вероятности',p(`Условие: Q действия − Q покоя > ${v(R.restThreshold)}. Если есть допущенные действия, покой исключается из жеребьёвки. Вероятности рассчитываются по прежней температурной формуле с поправкой количества допущенных целей каждой операции; заблокированные цели не увеличивают знаменатель. Одна функция распределения используется и для выбора, и для ожидаемого продолжения при обучении.`)
 +p('На старте, после завершения и физического срыва вызывается основной мозг. Совпавшие причины объединяются. Во время покоя или прерываемого процесса малый диспетчер может запросить пересмотр. Если выбран тот же продолжающийся процесс, его прогресс сохраняется; выбор другого действия или покоя отменяет его без возврата потраченного. Роды добровольно не прерываются.')
 +p(`Диспетчер получает давность основного решения: x = 1 / (1 + t / τ), где τ = ${v(R.timerScaleT,'Т')}. t отсчитывается после последнего основного решения, включая решение снова остаться в покое. Обычная проверка диспетчера отсчёт не сбрасывает. Обязательного пробуждения по таймеру нет.`))
 +p(`См. ${a('learning','обучение')}, ${a('time','порядок событий')}, ${a('actions','исполнение действий')}, ${a('brain-cost','оплату вычислений')}.`),

 'guide-brain-cost-body':
 p('Работа мозга расходует энергию. Основной выбор, личное обучение и проверки диспетчера учитываются отдельно. Цена зависит от условного числа выполненных операций; время работы компьютера измеряется отдельно и не влияет на физику мира.')
 +table('Что оплачивается',['Работа','Правило'],[
 ['Основной выбор',`Базовые ставки ${v(DECISION_COST)} и ${v(REPEAT_COST)} масштабируются по работе относительно эталонного оценщика. Повтор дешевле по принятому правилу ставок.`],
 ['Обучение','Оплачиваются выполненные фазы обучения. Если обучение выключено, их дополнительная цена отсутствует.'],
 ['Диспетчер',`Каждая фактическая проверка оплачивает подготовку признаков и активный план сети. Цена условной операции: ${v(DECISION_COST)} / ${v(ATTENTION_REFERENCE_OPERATIONS)} энергии.`]])
 +'<h4>Пример</h4>'
 +p('Диспетчер проверил обстановку и не запросил пересмотр. Его вычисления всё равно оплачиваются, но основной мозг и новый переход обучения ради этой проверки не запускаются. Добавление нейрона с нулевым исходящим весом сохраняет оценки, однако может увеличить работу активного пути и его цену.')
 +details('Эталон, порядок и дефицит',p('Цена операции диспетчера равна базовой ставке обычного решения, делённой на число операций полного эталонного цикла v13: семь видимых клеток, одиннадцать вариантов и шесть типов операций. Эталон фиксирован, не зависит от текущей численности и доступности действий.')
 +p('На границе подшага наблюдения и оценки строятся до списания новых вычислительных затрат. Затем мир списывает цену диспетчера и основного выбора/обучения. Такой порядок одинаков у локального исполнения и Workers. Смертельная оплата не начинает выбранное действие; дефицит оплачивается здоровьем по обычной физике.')
 +p('Наблюдатель хранит запрошенную стоимость по фазам. При нехватке энергии она отличается от фактически списанной энергии; энергетический баланс учитывает реальное списание. Средняя стоимость основного вызова и обучения делится на число основных вызовов, а проверки диспетчера имеют свой показатель. Покой также оплачивает физическую ставку прежнего ожидания.'))
 +p('Коэффициент цены вычислений в стартовых условиях одинаково умножает оплату основного выбора, обучения и малого мозга. Он строго положителен и сохраняется с миром и вариантом опыта. При значении меньше единицы вычисления дешевле; количество операций, веса и доступные мозгу сведения не меняются. Изменение формы применяется при новом запуске.')
 +p('Под настройками находится калькулятор полного энергетического бюджета начальной структуры. Он сопоставляет усвоение пищи со стоимостью движения, сбора, еды, ожидания и обеих сетей. Число перемещений на порцию можно менять. Условия расчёта раскрываются отдельно; роды исключены, пища доступна при сборе. Положительный остаток означает возможность накопления в этом режиме до заполнения тела, а не обещание выживания популяции.')
 +p('Если вычислитель вернул некорректную цену выполненного вызова, мир останавливается с сообщением об ошибке. Старые отсутствующие затраты не восстанавливаются предположениями.')
 +p(`См. ${a('energy','энергетический баланс')}, ${a('choice','пересмотр')}, ${a('structure-evolution','изменение структуры')}, ${a('performance','измерения скорости')}.`),

 'guide-time-body':
 p(`Одна Т состоит из ${v(SUBSTEPS,'подшагов')}; длительность подшага ${v(DT,'Т')}. Действия имеют прогресс и завершаются после своей физической длительности. Покой не является процессом с фиктивной длительностью.`)
 +'<h4>Пример движения</h4>'
 +p(`Движение занимает ${v(ACTION_DURATIONS[0]/SUBSTEPS,'Т')}. Пока оно не завершено, житель остаётся на исходной клетке. Пересмотр с продолжением сохраняет прогресс. Если основной мозг выбрал покой, движение прекращается, потраченная энергия не возвращается.`)
 +details('Порядок подшага','<ol><li>Увеличивается время, обновляются среда и наступившее восстановление пищи.</li><li>У всех жителей обновляются возраст, усвоение и расход действия либо покоя. Проверяется гибель.</li><li>Завершаются готовые действия; конкуренция за недостаточную пищу разрешается отдельной жеребьёвкой.</li><li>Прекращаются физически невозможные процессы и фиксируется общий снимок видимой деятельности.</li><li>Обновляются наблюдения и накопление субъективных последствий. Обязательные причины основного вызова объединяются; в остальных случаях при покое/обычном процессе проверяется диспетчер. Роды защищены от пересмотра.</li><li>При основном решении закрывается предыдущий переход обучения, оцениваются варианты, применяется политика покоя, затем списываются вычислительные затраты и принимается результат.</li></ol>'
 +p('Новорождённый впервые выбирает со следующего подшага. Между решениями покоя накапливаются последствия за фактическое время; проверки диспетчера не создают искусственных завершений. При сохранении записываются прогресс, покой, отметка последнего основного решения и ожидающий переход обучения. Локальный и параллельный пути проходят одинаковые фазы.'))
 +p(`См. ${a('choice','покой и пересмотр')}, ${a('learning','обучение во времени')}, ${a('actions','длительности действий')}, ${a('saves','продолжение мира')}.`),
};
